import '../core/network/api_client.dart'; import '../models/address.dart'; class AddressRepository { AddressRepository(this._api); final ApiClient _api; Future<List<AddressModel>> all() async { final r=await _api.get('/api/addresses'); return (r as List).whereType<Map<String,dynamic>>().map(AddressModel.fromJson).toList(); } Future<AddressModel> create(AddressDraft d) async=>AddressModel.fromJson(Map<String,dynamic>.from(await _api.post('/api/addresses',body:d.toJson()))); Future<AddressModel> update(String id,AddressDraft d) async=>AddressModel.fromJson(Map<String,dynamic>.from(await _api.put('/api/addresses/$id',body:d.toJson()))); Future<AddressModel> setDefault(String id) async=>AddressModel.fromJson(Map<String,dynamic>.from(await _api.put('/api/addresses/$id/default'))); Future<void> delete(String id) async=>_api.delete('/api/addresses/$id'); }